const data = $json;

// 1. Prioridade Total para o Código JP (O tiro de sniper)
// Aceita tanto id_imovel quanto codigo_ref conforme definimos na Tool
const codigo = data.id_imovel || data.codigo_ref;

if (codigo && codigo.toLowerCase() !== "null") {
  return {
    json: {
      id_imovel: codigo.toUpperCase().trim(),
      tipo_busca: "direta"
    }
  };
}

// 2. Limpeza e Normalização para buscas genéricas
// Pega o primeiro valor caso a IA mande uma lista ou texto sujo
const bairro = data.bairro ? data.bairro.split(",")[0].trim() : "";
const quartos = data.quartos ? parseInt(String(data.quartos).replace(/\D/g, "")) : 0;

// Trata o valor para garantir que seja um número puro (Ex: "1.2M" ou "1200000")
let valor = 0;
if (data.valor_maximo || data.valor_max) {
  const vRaw = String(data.valor_maximo || data.valor_max);
  valor = Number(vRaw.replace(/\D/g, ""));
}

// 3. Retorno Formatado para o Nó de Busca
return {
  json: {
    id_imovel: "NULL",
    bairro: bairro,
    finalidade: data.finalidade || data.Finalidade || "",
    valor_maximo: valor,
    quartos: isNaN(quartos) ? 0 : quartos,
    tipo_busca: "filtro"
  }
};

const supabaseResponse = $input.first().json;
const busca = $('Prepara Busca').first().json;

// Supabase REST API retorna array diretamente
const todos = Array.isArray(supabaseResponse) ? supabaseResponse : [];

// Normaliza nomes de campos para padrão do agente
const normalized = todos.map(d => ({
  id_imovel:         d.id_imovel,
  titulo:            d.titulo_comercial ?? '',
  descricao:         d.descricao_imovel ?? null,
  preco:             d.valor ?? 0,
  quartos:           d.quartos ?? 0,
  suites:            d.suites ?? 0,
  vagas:             d.vagas ?? 0,
  area:              d.metragem ?? null,
  bairro:            d.bairro ?? null,
  cidade:            'João Pessoa',
  tipo:              d.tipo_de_imovel ?? null,
  finalidade:        d.finalidade ?? null,
  status_publicacao: d.status_publicacao,
  fotos:             d.foto_principal ?? null,
  link:              d.link_do_imovel ?? d.link_redes_sociais ?? null,
}));

// Aplica filtros do Prepara Busca (client-side)
let resultado = normalized;

if (busca.tipo_busca === 'direta' && busca.id_imovel && busca.id_imovel !== 'NULL') {
  resultado = normalized.filter(i => i.id_imovel === busca.id_imovel);
} else {
  if (busca.bairro) {
    resultado = resultado.filter(i =>
      i.bairro && i.bairro.toLowerCase().includes(busca.bairro.toLowerCase())
    );
  }
  if (busca.quartos > 0) {
    resultado = resultado.filter(i => i.quartos >= busca.quartos);
  }
  if (busca.valor_maximo > 0) {
    resultado = resultado.filter(i => i.preco <= busca.valor_maximo);
  }
}

return [{
  json: {
    imoveis: resultado,
    total: resultado.length,
  }
}];
